import React, { useEffect, useState } from 'react';

const About = () => {
  const [revealed, setRevealed] = useState([]);

  useEffect(() => {
    const handleScroll = () => {
      const reveals = document.querySelectorAll('.reveal');
      reveals.forEach((el, index) => {
        const windowHeight = window.innerHeight;
        const elementTop = el.getBoundingClientRect().top;
        const elementVisible = 150;

        if (elementTop < windowHeight - elementVisible) {
          setRevealed(prev => [...new Set([...prev, index])]);
        }
      });
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const skills = [
    { category: 'Design', items: ['Brand Identity', 'Art Direction', 'Visual Design', 'Packaging'] },
    { category: 'Digital', items: ['UI/UX Design', 'Web Design', 'Motion Design', 'Photography'] },
    { category: 'Strategy', items: ['Brand Strategy', 'Creative Direction', 'Content Strategy', 'Market Research'] },
  ];

  const experience = [
    {
      period: '2021 — Present',
      title: 'Creative Director',
      company: 'Bellezaa Studio',
      description: 'Leading creative strategy and design for luxury beauty and lifestyle brands worldwide.',
    },
    {
      period: '2018 — 2021',
      title: 'Senior Designer',
      company: 'Maison Creative',
      description: 'Crafted visual identities and art direction for high-end cosmetics and wellness brands.',
    },
    {
      period: '2015 — 2018',
      title: 'Visual Designer',
      company: 'Luxe Agency',
      description: 'Developed brand systems and marketing materials for premium lifestyle clients.',
    },
  ];

  return (
    <div style={{ paddingTop: '120px' }}>
      {/* Hero */}
      <section className="section">
        <div className="container">
          <div className={`section-header reveal ${revealed.includes(0) ? 'active' : ''}`}>
            <p className="section-label">About</p>
            <h1 className="editorial-headline">
              I build systems that <br />
              businesses <em>grow faster</em>
            </h1>
            <p>I specialize in creating high-converting websites and AI-powered systems that generate leads, automate operations, and drive real business results.</p>
          </div>

          <div className="alternate-row">
            <div className={`reveal ${revealed.includes(1) ? 'active' : ''}`}>
              <div
                style={{
                  borderRadius: 'var(--radius-lg)',
                  overflow: 'hidden',
                  aspectRatio: '4/5',
                }}
              >
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    background: 'linear-gradient(135deg, #D4A5A5 0%, #E8C4C4 50%, #C9B896 100%)',
                    filter: 'saturate(0.8) contrast(0.95) sepia(0.1)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontFamily: 'var(--font-serif)',
                    fontStyle: 'italic',
                    fontSize: '1.5rem',
                    color: 'rgba(43, 43, 43, 0.3)',
                  }}
                >
                  Studio Portrait
                </div>
              </div>
            </div>

            <div className={`reveal ${revealed.includes(2) ? 'active' : ''}`}>
              <p style={{ fontSize: 'var(--text-lg)', lineHeight: '1.9', marginBottom: 'var(--space-6)' }}>
                Bellezaa is a creative studio founded on the belief that true luxury
                lies in restraint, in the thoughtful details, and in the harmony
                between form and feeling.
              </p>
              <p style={{ fontSize: 'var(--text-lg)', lineHeight: '1.9', marginBottom: 'var(--space-6)' }}>
                With over a decade of experience in beauty and lifestyle branding,
                we bring a discerning eye and meticulous craft to every project.
                Our approach is intentionally intimate—we take on select projects
                to ensure each receives the attention and care it deserves.
              </p>
              <p style={{ fontSize: 'var(--text-lg)', lineHeight: '1.9', marginBottom: 0 }}>
                Based in New York, we collaborate with visionary brands worldwide,
                creating visual languages that resonate with elegance and authenticity.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Skills */}
      <section className="section" style={{ backgroundColor: 'var(--bg-secondary)' }}>
        <div className="container">
          <div className={`section-header reveal ${revealed.includes(3) ? 'active' : ''}`}>
            <p className="section-label">Expertise</p>
            <h2 className="section-title">Areas of Focus</h2>
          </div>

          <div className="services-grid">
            {skills.map((skill, index) => (
              <div
                key={index}
                className={`service-card reveal ${revealed.includes(4 + index) ? 'active' : ''}`}
                style={{ transitionDelay: `${index * 100}ms` }}
              >
                <h3 className="service-title">{skill.category}</h3>
                <ul style={{ listStyle: 'none', padding: 0 }}>
                  {skill.items.map((item, i) => (
                    <li
                      key={i}
                      style={{
                        fontSize: 'var(--text-sm)',
                        color: 'var(--text-tertiary)',
                        padding: 'var(--space-2) 0',
                        borderBottom: i < skill.items.length - 1 ? '1px solid var(--border-primary)' : 'none',
                      }}
                    >
                      {item}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Experience */}
      <section className="section">
        <div className="container">
          <div className={`section-header reveal ${revealed.includes(7) ? 'active' : ''}`}>
            <p className="section-label">Experience</p>
            <h2 className="section-title">Career Path</h2>
          </div>

          <div className="experience-list">
            {experience.map((job, index) => (
              <div
                key={index}
                className={`experience-item reveal ${revealed.includes(8 + index) ? 'active' : ''}`}
                style={{ transitionDelay: `${index * 150}ms` }}
              >
                <div className="experience-year">{job.period}</div>
                <div className="experience-content">
                  <h3>{job.title}</h3>
                  <p className="company">{job.company}</p>
                  <p className="description">{job.description}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};

export default About;
